using System.Reflection;using System.Text.Json;using System.Text.Json.Nodes;using System.Diagnostics;
namespace RisingLands;
public static class BaseDefenseTests {
 static object? Invoke(Simulation s,string name,params object[] args)=>typeof(Simulation).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,args);
 public static Simulation Load(string root,int mission=5,int extra=0){var w=LegacyAssets.Map(PackageLayout.Asset(root,$"CD/WORLD/MONDE{mission:00}.ETA"));if(extra>0){var template=w.Units.First(a=>a.Owner==0&&a.Type==0);for(int o=1;o<=3;o++)for(int n=0;n<extra;n++){var a=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(template))!;a.Owner=o;a.Slot=w.Units.Max(a=>a.Slot)+1;var home=w.Buildings.FirstOrDefault(b=>b.Owner==o);if(home==null)continue;a.X=Math.Clamp((home.Cell&255)-4+n%3,0,w.Width-1)*1024;a.Y=Math.Clamp((home.Cell>>8)+6+n/3,0,w.Height-1)*1024;w.Units.Add(a);}}new VisualCatalog().Apply(w);return new(w);}
 public static void Run(string root,string output){int checks=0;void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}var samples=new List<object>();
 foreach(int owner in Enumerable.Range(1,3)){
  var s=Load(root,5,8);var home=s.World.Buildings.First(b=>b.Owner==owner&&b.Type==2);var enemies=s.World.Units.Where(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a)).ToArray();var enemy=enemies.First();int near=home.Cell-2+6*256;enemy.X=(near&255)*1024;enemy.Y=(near>>8)*1024;
  Invoke(s,"UpdateBaseDefense",owner);var d=s.BaseDefenseFor(owner);Check(d.Threats.Any(t=>t.Slot==enemy.Slot),"visible invader observed clan "+owner);Check(d.Guards.Count>=3,"garrison assigned clan "+owner);Check(d.Guards.Values.Any(g=>g.Target==enemy.Slot),"interception ordered clan "+owner);Check(d.Guards.Values.Any(g=>g.Target<0),"reserve retained against lone distraction clan "+owner);
  var guards=s.World.Units.Where(a=>d.Guards.ContainsKey(a.Slot)).ToArray();Invoke(s,"ExecuteBaseDefense",owner);Check(guards.Any(a=>a.AttackTarget==enemy.Slot),"defenders actually acquire attacker clan "+owner);
  foreach(var a in guards)a.AttackTarget=-1;enemy.X=0;enemy.Y=0;foreach(var t in d.Threats)t.Seen=-1000;d.LastUpdate=-1;Invoke(s,"UpdateBaseDefense",owner);Invoke(s,"ExecuteBaseDefense",owner);Check(guards.All(a=>a.AttackTarget!=enemy.Slot),"no pursuit across map clan "+owner);
  Check(d.Guards.Values.Select(g=>g.Sector).Distinct().Count()>=2,"guards distributed in sectors clan "+owner);
  d.LastUpdate=-1;s.Campaign.Alliances[owner]=true;enemy.X=(near&255)*1024;enemy.Y=(near>>8)*1024;Invoke(s,"UpdateBaseDefense",owner);Check(!d.Threats.Any(t=>t.Owner==0),"ally excluded from threats clan "+owner);
  var third=s.World.Units.First(a=>a.Owner==(owner%3+1)&&a.Type==0&&VisualCatalog.Visible(a));third.X=(near&255)*1024;third.Y=(near>>8)*1024;d.LastUpdate=-1;Invoke(s,"UpdateBaseDefense",owner);Check(d.Threats.Any(t=>t.Slot==third.Slot),"ally clan still defends against third parties "+owner);
  s.Campaign.Alliances[owner]=false;d.LastUpdate=-1;Invoke(s,"ObserveBaseAttack",enemy.Slot,home);Invoke(s,"UpdateBaseDefense",owner);Check(d.Mode=="Invasao"&&d.IncidentCell==home.Cell,"building attack activates invasion alert clan "+owner);
  samples.Add(new{Owner=owner,d.Mode,d.GarrisonTarget,d.ThreatPower,d.RequiredPower,Guards=d.Guards.Count});
 }
 var tactical=Load(root,5,8);int o=1;var core=tactical.World.Buildings.First(b=>b.Owner==o&&b.Type==2);var fighters=tactical.World.Units.Where(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a)).Take(3).ToArray();for(int k=0;k<fighters.Length;k++){int cell=core.Cell+(k==2?-5:2)+6*256;fighters[k].X=(cell&255)*1024;fighters[k].Y=(cell>>8)*1024;}Invoke(tactical,"UpdateBaseDefense",o);var td=tactical.BaseDefenseFor(o);Check(td.Threats.Count>=2,"multi-attacker threat captured");Check(td.Guards.Values.Where(g=>g.Target>=0).Select(g=>g.Target).Distinct().Count()>=2,"damage distributed among threats");double low=td.RequiredPower;double power=(double)Invoke(tactical,"DefenseTypePower",0,100)!;double injured=(double)Invoke(tactical,"DefenseTypePower",0,10)!;Check(power>injured,"remaining health changes force assessment");td.LastUpdate=-1;foreach(var actor in fighters)actor.Health=1;Invoke(tactical,"UpdateBaseDefense",o);Check(td.RequiredPower<low,"weakened attackers require fewer reinforcements");
 foreach(var actor in fighters){actor.X=0;actor.Y=0;}td.Threats.Clear();td.LastUpdate=-1;Invoke(tactical,"ObserveBaseAttack",fighters[0].Slot,core);Invoke(tactical,"UpdateBaseDefense",o);Check(td.Mode=="Invasao"&&td.Guards.Values.Any(g=>g.Anchor==core.Cell),"unknown shooter triggers protection of damaged building");
 var econ=Load(root);var economicHome=econ.World.Buildings.First(b=>b.Owner==1&&b.Type==2);var barracks=new Building(6000,1,1,economicHome.Cell-12);econ.World.Buildings.Add(barracks);var ids=econ.World.BuildingResidents[economicHome.Slot].Take(3).ToList();econ.World.BuildingResidents[economicHome.Slot].RemoveAll(ids.Contains);econ.World.BuildingResidents[barracks.Slot]=ids;var ds=econ.BaseDefenseFor(1);ds.Mode="Invasao";ds.GarrisonTarget=12;econ.World.Resources[1]=0;Check(!(bool)Invoke(econ,"TrainOpponent",1,barracks,0)!,"defensive recruitment cannot create free soldiers");econ.World.Resources[1]=200;econ.World.Resources[5]=200;econ.World.Resources[9]=200;int food=econ.World.Resources[1],rock=econ.World.Resources[5],parts=econ.World.Resources[9];bool trained=(bool)Invoke(econ,"TrainOpponent",1,barracks,0)!;Check(trained,"stocked occupied barracks starts defensive recruitment");var price=econ.TrainingRule(0);Check(econ.World.Resources[1]==food-price.Food&&econ.World.Resources[5]==rock-price.Rock&&econ.World.Resources[9]==parts-price.Parts,"defensive production pays all real costs");Check(!(bool)Invoke(econ,"TrainOpponent",1,barracks,0)!,"active producer rejects duplicate recruitment");
 Simulation MagicFixture(){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE05.ETA"));var home=w.Buildings.First(b=>b.Owner==1&&b.Type==2);w.Buildings.Add(new(6100,6,1,home.Cell-12));var a=JsonSerializer.Deserialize<Actor>(JsonSerializer.Serialize(w.Units.First(a=>a.Owner==0&&a.Type==0)))!;a.Slot=6101;a.Type=4;a.Owner=1;a.X=((home.Cell&255)-2)*1024;a.Y=((home.Cell>>8)+6)*1024;w.Units.Add(a);new VisualCatalog().Apply(w);return new(w);}
 var magic=MagicFixture();var caster=magic.World.Units.Single(a=>a.Slot==6101);var foe=magic.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));foe.X=caster.X+1024;foe.Y=caster.Y;caster.Mana=magic.ManaMaximum(caster);int targetCell=foe.Y/1024*256+foe.X/1024;Check(!magic.CanCastSpell(caster,1,targetCell,foe),"enemy cannot use unlearned spell");
 magic.World.Resources[1]-=(ushort)magic.Spell(1).Food;magic.World.Resources[5]-=(ushort)magic.Spell(1).Rock;magic.World.Resources[9]-=(ushort)magic.Spell(1).Parts;magic.Special.Learning.Add(new(){Owner=1,Building=6100,Spell=1,Progress=magic.Spell(1).Learning*100,Finished=true});Check(magic.SpellLearned(1,1)&&!magic.SpellLearned(1,0),"knowledge belongs to each clan");int mana=caster.Mana;Invoke(magic,"UpdateBaseDefense",1);Invoke(magic,"DefensiveSupport",1);Check(foe.PetrifiedUntil>magic.Tick&&caster.Mana==mana-magic.Spell(1).Mana,"defensive druid petrifies observed enemy and pays mana");var mc=MagicFixture();mc.Restore(magic.Serialize());Check(mc.Serialize()==magic.Serialize(),"enemy spell knowledge and active effect persist");
 caster.Mana=0;Check(!magic.CanCastSpell(caster,1,targetCell,foe),"enemy cannot cast without mana");caster.Mana=magic.ManaMaximum(caster);magic.Campaign.Alliances[1]=true;Check(!magic.CanCastSpell(caster,1,targetCell,foe),"enemy druid does not petrify allied player");
 var learn=SpecialV66Tests.Load(root);int library=ProductionV65Tests.Staff(learn,6);learn.Special.Learning.Add(new(){Owner=1,Building=6100,Spell=0});Check(learn.CanLearnSpell(0,library),"enemy study does not block player study");
 var natural=Load(root);for(int i=0;i<90;i++)natural.Step();var saved=natural.Serialize();var copy=Load(root);copy.Restore(saved);Check(copy.Serialize()==saved,"new defensive state saves exactly");for(int i=0;i<300;i++){natural.Step();copy.Step();}Check(copy.Serialize()==natural.Serialize(),"defense resumes deterministically");
 var legacy=JsonNode.Parse(saved)!;legacy["Version"]=39;legacy["Opponent"]!.AsObject().Remove("BaseDefenses");var old=Load(root);old.Restore(legacy.ToJsonString());old.Step();Check(old.OpponentEnabled,"old saves without defenses import");
 var noEnemies=Load(root,6);for(int i=0;i<60;i++)noEnemies.Step();Check(noEnemies.Opponent.BaseDefenses.Count==0,"exploration mission6 remains without adversaries");
 var bad=JsonNode.Parse(saved)!;bad["Opponent"]!["BaseDefenses"]!["1"]!["ThreatPower"]=-1;string prior=copy.Serialize();try{copy.Restore(bad.ToJsonString());throw new Exception("Malformed defense accepted");}catch(InvalidDataException){}Check(copy.Serialize()==prior,"invalid defensive state rejected atomically");
 var wall=Load(root,5,8);typeof(Simulation).GetProperty("Tick")!.SetValue(wall,18000L);wall.Campaign.EnemyLevels[2]=new[]{19,24,20,18};foreach(int k in new[]{2,6,10})wall.World.Resources[k]=2000;var colonists=wall.World.Units.Where(a=>a.Owner==2&&a.Type==9&&a.Health>0).Take(3).ToArray();int ci=0;foreach(int bt in new[]{2,3,4}){var b=wall.World.Buildings.FirstOrDefault(b=>b.Owner==2&&b.Type==bt);if(b==null){b=new Building(6200+bt,bt,2,wall.World.Buildings.First(b=>b.Owner==2&&b.Type==2).Cell-12+bt*256);wall.World.Buildings.Add(b);}int id=colonists[ci++].Slot;foreach(var list in wall.World.BuildingResidents.Values)list.Remove(id);wall.World.BuildingResidents[b.Slot]=new(){id};wall.World.Units.First(a=>a.Slot==id).LegacyState=14;}var economy=wall.EconomyFor(2);economy.Initialized=true;economy.StableTicks=36000;economy.Income=20;economy.Maintenance=1;economy.KnownFood=100;economy.Reserve=20;Invoke(wall,"UpdateBaseDefense",2);Check(wall.EconomyReady(2),"fortification fixture has functioning occupied economy");int beforeWall=wall.World.Resources[6];bool fortified=(bool)Invoke(wall,"TryDefenseFortification",2)!;Check(fortified&&wall.Constructions.Last().Type==9&&wall.World.Resources[6]==beforeWall-wall.Rule(9).Rock,$"yellow builds legal paid defensive flank wall mode={wall.BaseDefenseFor(2).Mode} gap={Invoke(wall,"DefenseShortfall",2)} workers={wall.World.Units.Count(a=>a.Owner==2&&a.Type==7&&VisualCatalog.Visible(a))} unlocked={wall.OpponentBuildingUnlocked(2,9)} posts={wall.BaseDefenseFor(2).Guards.Count}");var wallHome=wall.World.Buildings.First(b=>b.Owner==2&&b.Type==2);int homeY=(wallHome.Cell>>8)+wall.Rule(2).Height/2;Check(Math.Abs((wall.Constructions.Last().Cell>>8)-homeY)>=4,"defensive wall preserves central opening");Check(!(bool)Invoke(wall,"TryDefenseFortification",1)!,"fortress wall policy does not leak to other profiles");
 var study=MagicFixture();study.Campaign.EnemyLevels[1][3]=18;foreach(int k in new[]{1,5,9})study.World.Resources[k]=2000;var temple=study.World.Buildings.First(b=>b.Slot==6100);var sanctuary=study.World.Buildings.First(b=>b.Owner==1&&b.Type==2);int resident=study.World.BuildingResidents[sanctuary.Slot][0];study.World.BuildingResidents[sanctuary.Slot].Remove(resident);study.World.BuildingResidents[temple.Slot]=new(){resident};study.BaseDefenseFor(1).GarrisonTarget=24;int studyFood=study.World.Resources[1];Invoke(study,"DefensiveSupport",1);Check(study.Special.Learning.Any(j=>j.Owner==1&&!j.Finished)&&study.World.Resources[1]==studyFood-study.Spell(study.Special.Learning.Last().Spell).Food,"enemy starts technology-unlocked paid spell learning");Invoke(study,"DefensiveSupport",1);Check(study.Special.Learning.Count==1,"enemy cannot duplicate active spell learning");
 var changed=Load(root,5,8);Invoke(changed,"UpdateBaseDefense",1);int exchanged=changed.BaseDefenseFor(1).Guards.Keys.First();changed.World.Units.First(a=>a.Slot==exchanged).Owner=0;changed.Serialize();Check(!changed.BaseDefenseFor(1).Guards.ContainsKey(exchanged),"changed owner clears stale garrison assignment before save");var timer=Stopwatch.StartNew();var perf=Load(root);for(int i=0;i<1800;i++)perf.Step();timer.Stop();samples.Add(new{Ticks=1800,Milliseconds=timer.ElapsedMilliseconds});Check(!perf.MissionLost,"one minute natural opening remains playable");
 File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=checks,Passed=true,Samples=samples,Limit="Engine simulations; controlled unit placement and extra armies only in tactical fixtures"},new JsonSerializerOptions{WriteIndented=true}));
 }
